<template><div class="paper-page"><h2>📝 CSP 整卷测评</h2><p class="hint">选择完整试卷，布置给学生并查看每题答题情况。</p><div class="layout"><section class="panel"><h3>新建整卷任务</h3><div class="form"><label>级别<select v-model="form.level"><option>CSP-J</option><option>CSP-S</option></select></label><label>年份<select v-model.number="form.year"><option v-for="year in years" :key="year">{{ year }}</option></select></label><label>任务名称<input v-model="form.title" placeholder="默认使用试卷名称"></label><label>截止时间<input v-model="form.deadline" type="datetime-local"></label></div><h4>学生</h4><div class="actions"><button @click="selectedIds = students.map(s => s.id)">全选</button><button @click="selectedIds = []">清空</button><span>已选 {{ selectedIds.length }} 人</span></div><div class="student-grid"><label v-for="student in students" :key="student.id"><input v-model="selectedIds" type="checkbox" :value="student.id"><span>{{ student.name }}</span><small>{{ student.class_name || '未分班' }}</small></label></div><button class="create-button" :disabled="busy || !selectedIds.length" @click="createAssignment">{{ busy ? '保存中…' : '布置整卷' }}</button></section><section class="panel"><h3>已布置整卷</h3><p v-if="!assignments.length" class="empty">还没有整卷任务。</p><button v-for="item in assignments" :key="item.id" class="assignment" @click="loadDetail(item.id)"><strong>{{ item.title }}</strong><span>{{ item.level }} · {{ item.year }} · {{ item.completed_count || 0 }}/{{ item.student_count || 0 }} 人完成 · {{ item.submission_count || 0 }} 题次</span></button><div v-if="detail" class="detail"><header><div><h3>{{ detail.title }}</h3><p>{{ detail.level }} {{ detail.year }} · {{ detail.students.length }} 人 · 题库分值 {{ detail.maxScore }}</p></div><div class="detail-actions"><select v-model.number="extraStudentId"><option :value="0">补充学生</option><option v-for="student in availableExtraStudents" :key="student.id" :value="student.id">{{ student.name }}</option></select><button @click="addStudent" :disabled="busy || !extraStudentId">添加</button><button v-if="!detail.analysisReleasedAt" class="primary" @click="release" :disabled="busy">开放整卷解析</button><b v-else class="released">解析已开放</b></div></header><div class="summary"><span v-for="item in detail.students" :key="item.studentId">{{ item.name }}：{{ item.submitted }}/{{ item.total }}，{{ item.score }}/{{ item.maxScore }}</span></div><h4>每题答题情况</h4><article v-for="item in detail.questions" :key="item.questionId" class="question-stat"><div><strong>{{ item.type }} {{ item.number }}</strong><span>{{ item.submitted }}/{{ item.total }} 人提交 · 平均 {{ item.averagePercent == null ? '—' : item.averagePercent + '%' }}</span></div><details><summary>查看明细</summary><p v-for="answer in item.details" :key="answer.studentId" :class="answer.submitted ? (answer.correct ? 'ok' : 'bad') : 'muted'"><b>{{ answer.name }}</b>：{{ answer.submitted ? (answer.score + '/' + answer.maxScore + (answer.correct ? ' 正确' : ' 错误')) : '未提交' }}<small v-if="answer.submitted">；作答 {{ formatAnswers(answer.answers) }}<span v-if="answer.parts?.length">；小问 {{ answer.parts.map(part => part.correct ? '对' : '错').join('、') }}</span></small></p></details></article></div></section></div><p v-if="error" class="error">{{ error }}</p></div></template>

<script setup>
import { computed, onMounted, ref } from 'vue';
import { authFetch } from '../utils/auth';

const years = [2019, 2020, 2021, 2022, 2023, 2024, 2025];
const students = ref([]); const selectedIds = ref([]); const assignments = ref([]); const detail = ref(null); const extraStudentId = ref(0); const busy = ref(false); const error = ref('');
const availableExtraStudents = computed(() => students.value.filter(student => !detail.value?.students?.some(item => Number(item.studentId) === Number(student.id))));
const form = ref({ level: 'CSP-J', year: 2025, title: '', deadline: '' });
function readJson(response) { return response.json().then(data => { if (!response.ok) throw new Error(data.error || '请求失败'); return data; }); }
function formatAnswers(answers) { return Object.values(answers || {}).map(value => Array.isArray(value) ? value.join('、') : String(value || '')).filter(Boolean).join('；') || '—'; }
async function load() { error.value = ''; try { const [studentResponse, assignmentResponse] = await Promise.all([authFetch('/api/auth/students'), authFetch('/api/csp-papers/assignments')]); students.value = await readJson(studentResponse); assignments.value = await readJson(assignmentResponse); selectedIds.value = students.value.map(item => item.id); } catch (e) { error.value = e.message; } }
async function createAssignment() { busy.value = true; error.value = ''; try { const data = await readJson(await authFetch('/api/csp-papers/assignments', { method: 'POST', body: JSON.stringify({ ...form.value, studentIds: selectedIds.value }) })); detail.value = data; assignments.value = await readJson(await authFetch('/api/csp-papers/assignments')); form.value.title = ''; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function loadDetail(id) { error.value = ''; try { detail.value = await readJson(await authFetch(`/api/csp-papers/assignments/${id}`)); } catch (e) { error.value = e.message; } }
async function addStudent() { if (!detail.value || !extraStudentId.value) return; busy.value = true; error.value = ''; try { detail.value = await readJson(await authFetch(`/api/csp-papers/assignments/${detail.value.id}/students`, { method: 'POST', body: JSON.stringify({ studentIds: [extraStudentId.value] }) })); extraStudentId.value = 0; } catch (e) { error.value = e.message; } finally { busy.value = false; } }
async function release() { if (!detail.value || !confirm('确定开放这份整卷的解析吗？已提交学生将立即看到对错和解析。')) return; busy.value = true; try { detail.value = await readJson(await authFetch(`/api/csp-papers/assignments/${detail.value.id}/release`, { method: 'POST', body: '{}' })); } catch (e) { error.value = e.message; } finally { busy.value = false; } }
onMounted(load);
</script>

<style scoped>
.paper-page{height:100%;overflow:auto;padding:26px 30px 60px;background:#f7f9fc;color:#172033}.paper-page h2{margin:0;color:#3730a3}.hint{color:#64748b}.layout{display:grid;grid-template-columns:minmax(320px,420px) minmax(420px,1fr);gap:18px}.panel{padding:20px;border:1px solid #dbe3f0;border-radius:14px;background:#fff;box-shadow:0 5px 18px #1e293b0b}.form{display:grid;gap:10px}.form label{display:grid;gap:5px;color:#475569;font-weight:700;font-size:13px}.form input,.form select{padding:10px;border:1px solid #cbd5e1;border-radius:8px;font:inherit}.actions{display:flex;gap:8px;align-items:center;margin:10px 0}.actions span{color:#64748b;font-size:13px}.student-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;max-height:280px;overflow:auto;margin-bottom:14px}.student-grid label{display:grid;grid-template-columns:auto 1fr;gap:3px 7px;padding:9px;border:1px solid #e2e8f0;border-radius:8px}.student-grid small{grid-column:2;color:#94a3b8}.primary{background:#4f46e5!important;color:white!important;border-color:#4f46e5!important}.assignment{display:flex;width:100%;flex-direction:column;align-items:flex-start;gap:4px;margin:8px 0;padding:12px;border:1px solid #c7d2fe;border-radius:9px;background:#eef2ff;color:#3730a3;text-align:left;cursor:pointer}.assignment span{color:#64748b;font-size:12px}.detail{margin-top:20px;border-top:1px solid #e2e8f0;padding-top:16px}.detail header{display:flex;justify-content:space-between;gap:10px;align-items:start}.detail-actions{display:flex;align-items:center;gap:7px;flex-wrap:wrap}.detail-actions select{padding:9px;border:1px solid #cbd5e1;border-radius:8px;color:#475569}.detail header h3{margin:0}.detail header p{color:#64748b;font-size:13px}.released{color:#15803d}.summary{display:flex;flex-wrap:wrap;gap:7px;margin:10px 0}.summary span{padding:5px 8px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:12px}.question-stat{padding:10px 0;border-top:1px solid #eef2f7}.question-stat>div{display:flex;justify-content:space-between;gap:10px}.question-stat span{color:#64748b;font-size:12px}.question-stat summary{color:#4f46e5;cursor:pointer;margin-top:7px}.question-stat p{margin:5px 0;font-size:13px}.ok{color:#15803d}.bad{color:#b91c1c}.muted{color:#94a3b8}.question-stat small{color:inherit}.empty,.error{color:#b91c1c}.error{margin-top:14px}@media(max-width:900px){.layout{grid-template-columns:1fr}.paper-page{padding:18px 14px}.student-grid{grid-template-columns:1fr}}
.create-button{appearance:none;display:flex;width:100%;align-items:center;justify-content:center;min-height:46px;margin-top:4px;padding:0 20px;border:1px solid #4f46e5;border-radius:10px;background:linear-gradient(135deg,#635bff,#4f46e5);box-shadow:0 8px 18px rgba(79,70,229,.22);color:#fff;font:inherit;font-size:16px;font-weight:700;letter-spacing:.03em;cursor:pointer;transition:transform .16s ease,box-shadow .16s ease,background .16s ease}.create-button:hover:not(:disabled){background:linear-gradient(135deg,#7168ff,#4338ca);box-shadow:0 10px 22px rgba(79,70,229,.3);transform:translateY(-1px)}.create-button:active:not(:disabled){box-shadow:0 4px 10px rgba(79,70,229,.22);transform:translateY(0)}.create-button:focus-visible{outline:3px solid rgba(99,91,255,.28);outline-offset:2px}.create-button:disabled{border-color:#cbd5e1;background:#e2e8f0;box-shadow:none;color:#94a3b8;cursor:not-allowed}</style>
